package trust

import (
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// dsseVector is one file in testdata/dsse. Vectors are generated by
// TestGenerateVectors (-update) and committed; the committed bytes are the oracle.
type dsseVector struct {
	Description string          `json:"description"`
	PayloadType string          `json:"payload_type"`
	Keyring     json.RawMessage `json:"keyring"`
	Revocations json.RawMessage `json:"revocations,omitempty"`
	Envelope    json.RawMessage `json:"envelope"`
	Want        struct {
		OK    bool   `json:"ok"`
		KID   string `json:"kid,omitempty"`
		Error string `json:"error,omitempty"`
	} `json:"want"`
}

func TestDSSE(t *testing.T) {
	for _, name := range []string{"good", "bad-sig", "wrong-purpose", "revoked", "outside-window"} {
		t.Run(name, func(t *testing.T) {
			raw, err := os.ReadFile(filepath.Join("testdata", "dsse", name+".json"))
			if err != nil {
				t.Fatal(err)
			}
			var v dsseVector
			if err := json.Unmarshal(raw, &v); err != nil {
				t.Fatal(err)
			}
			keys, err := parseKeyring(v.Keyring, false)
			if err != nil {
				t.Fatalf("keyring: %v", err)
			}
			kr, err := newKeyring(keys)
			if err != nil {
				t.Fatal(err)
			}
			revs := NoRevocations()
			if len(v.Revocations) > 0 {
				if revs, err = ParseRevocations(v.Revocations); err != nil {
					t.Fatalf("revocations: %v", err)
				}
			}
			got, err := kr.Verify(v.Envelope, v.PayloadType, revs)
			if v.Want.OK {
				if err != nil {
					t.Fatalf("want accept, got %v", err)
				}
				if got.KeyID != v.Want.KID || len(got.Payload) == 0 {
					t.Fatalf("got kid %q payload %d bytes, want kid %q", got.KeyID, len(got.Payload), v.Want.KID)
				}
				return
			}
			if err == nil {
				t.Fatalf("want reject containing %q, got accept", v.Want.Error)
			}
			if !strings.Contains(err.Error(), v.Want.Error) {
				t.Fatalf("error %q does not contain %q", err, v.Want.Error)
			}
		})
	}
}

// TestDSSEValueFree: envelope fields are read before any signature check, so
// an error must not echo them (a hostile endpoint could reflect the bearer
// token into diagnostics).
func TestDSSEValueFree(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("testdata", "dsse", "good.json"))
	if err != nil {
		t.Fatal(err)
	}
	var v dsseVector
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	keys, err := parseKeyring(v.Keyring, false)
	if err != nil {
		t.Fatal(err)
	}
	kr, err := newKeyring(keys)
	if err != nil {
		t.Fatal(err)
	}
	const marker = "BOBTHECORP-MARKER-1"
	// A keyid passes kidRE but can carry 32 hex-encoded bytes of anything.
	hexKid := "sha256:" + hex.EncodeToString([]byte(marker+"-PADDED-32BYT"))
	sig := `{"keyid":"` + hexKid + `","sig":"AA=="}`
	_, err = kr.Verify([]byte(`{"payloadType":"`+v.PayloadType+`","payload":"","signatures":[`+sig+`,`+sig+`]}`), v.PayloadType, NoRevocations())
	if err == nil || strings.Contains(err.Error(), hexKid[7:]) {
		t.Errorf("duplicate keyid: error %v", err)
	}
	_, err = kr.Verify([]byte(`{"payloadType":"`+v.PayloadType+`","payload":"","signatures":[`+sig+`]}`), v.PayloadType, NoRevocations())
	if err == nil || strings.Contains(err.Error(), hexKid[7:]) {
		t.Errorf("unknown keyid: error %v", err)
	}
	for _, env := range []string{
		`{"payloadType":"Bearer ` + marker + `","payload":"","signatures":[]}`,
		`{"payloadType":"x","payload":"","signatures":[],"` + marker + `":1}`,
		`{"payloadType":"x","payloadType":"` + marker + `","payload":"","signatures":[]}`,
		`{"payloadType":"x","` + marker + `":1,"` + marker + `":2}`,
	} {
		_, err := kr.Verify([]byte(env), v.PayloadType, NoRevocations())
		if err == nil || strings.Contains(err.Error(), marker) {
			t.Errorf("envelope %s: error %v", env, err)
		}
	}
}

// TestDSSEPAE uses the example from the DSSE protocol spec.
func TestDSSEPAE(t *testing.T) {
	got := string(PAE("http://example.com/HelloWorld", []byte("hello world")))
	want := "DSSEv1 29 http://example.com/HelloWorld 11 hello world"
	if got != want {
		t.Fatalf("PAE = %q, want %q", got, want)
	}
}

// TestDSSEFixedReasons: every rejection Verify makes before a signature
// counts uses a fixed reason, and a known key is named by its signature
// index, never its keyid. No character, number or keyid of the unsigned
// envelope reaches the error.
func TestDSSEFixedReasons(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("testdata", "dsse", "good.json"))
	if err != nil {
		t.Fatal(err)
	}
	var v dsseVector
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	keys, err := parseKeyring(v.Keyring, false)
	if err != nil {
		t.Fatal(err)
	}
	kr, err := newKeyring(keys)
	if err != nil {
		t.Fatal(err)
	}
	var good envelope
	if err := json.Unmarshal(v.Envelope, &good); err != nil {
		t.Fatal(err)
	}
	pt := v.PayloadType
	kid := good.Signatures[0].KeyID
	sig := `{"keyid":"` + kid + `","sig":"` + good.Signatures[0].Sig + `"}`
	nine := strings.Repeat(`{"keyid":"sha256:`+strings.Repeat("a", 64)+`","sig":"AA=="},`, 8) + sig
	for name, c := range map[string]struct{ env, pt, want string }{
		"syntax char":     {`{"payloadType":Z}`, pt, "dsse: invalid JSON"},
		"type number":     {`{"payloadType":"` + pt + `","payload":"","signatures":987654321}`, pt, "dsse: envelope has the wrong shape"},
		"signature count": {`{"payloadType":"` + pt + `","payload":"","signatures":[` + nine + `]}`, pt, "dsse: need 1 to 8 signatures"},
		"sig base64":      {`{"payloadType":"` + pt + `","payload":"","signatures":[{"keyid":"` + kid + `","sig":"A@=="}]}`, pt, "dsse: signature 0: invalid base64"},
		"payload base64":  {`{"payloadType":"` + pt + `","payload":"A@==","signatures":[` + sig + `]}`, pt, "dsse: payload: invalid base64"},
		"unknown type":    {string(v.Envelope), "application/x-" + kid, "dsse: unknown payload type"},
		"known key purpose": {strings.Replace(string(v.Envelope), PayloadBundleManifest, PayloadProfile, 1), PayloadProfile,
			"dsse: no valid signature: signature 0: key purpose bundle, payload needs profile"},
		"known key bad sig": {`{"payloadType":"` + pt + `","payload":"` + good.Payload + `","signatures":[{"keyid":"` + kid + `","sig":"AA=="}]}`, pt,
			"dsse: no valid signature: signature 0: signature invalid"},
	} {
		_, err := kr.Verify([]byte(c.env), c.pt, NoRevocations())
		if err == nil || err.Error() != c.want {
			t.Errorf("%s: error %v, want %q", name, err, c.want)
		}
	}
}
